Una suite que atrapa todo:

```js
test("funciona a la primera: una sola llamada", async () => {
  let llamadas = 0;
  const pedir = async () => { llamadas++; return "datos"; };
  await conReintentos(pedir, 3);
  expect(llamadas).toBe(1);
});
test("falla 2 veces y luego funciona", async () => {
  let llamadas = 0;
  const pedir = async () => {
    llamadas++;
    if (llamadas < 3) throw new Error(`fallo ${llamadas}`);
    return "datos";
  };
  expect(await conReintentos(pedir, 3)).toBe("datos");
});
test("falla siempre: 3 llamadas y el último error", async () => {
  let llamadas = 0;
  const pedir = async () => { llamadas++; throw new Error(`fallo ${llamadas}`); };
  await expect(conReintentos(pedir, 3)).rejects.toThrow("fallo 3");
  expect(llamadas).toBe(3);
});
```
